-- Import the profiles from Plater
function PlaterProfileImport.ImportPlaterProfile(platerModule)
    -- Check if Plater is loaded
    if not IsAddOnLoaded("Plater") then
        return false, "Plater is not installed or enabled"
    end
    
    -- Check if we have a valid module
    if not platerModule or not platerModule.db or not platerModule.db.profile then
        return false, "Invalid VUIPlater module"
    end
    
    -- Get profile string from the file
    local profileString = PlaterProfileImport.GetProfileString()
    if not profileString or profileString == "" then
        return false, "No profile string found"
    end
    
    -- Import the profile to Plater
    local success, errorMsg = PlaterProfileImport.ImportToPlater(profileString)
    if not success then
        return false, errorMsg or "Failed to import profile"
    end
    
    -- Report success
    return true, "Successfully imported VUIPlater profile to Plater"
end

-- Get the profile string from the file
function PlaterProfileImport.GetProfileString()
    -- Load the string from PlaterProfileImport.lua
    local profileString = ""
    
    -- Try to get it from the addon's global variable first
    if M.PLATER_PROFILE_STRING and M.PLATER_PROFILE_STRING ~= "" then
        profileString = M.PLATER_PROFILE_STRING
    else
        -- If not available, use the string from Plater_profile.lua
        local path = "Interface\\AddOns\\VUI\\VModules\\VUIPlater\\Plater_profile.lua"
        local f = io.open(path, "r")
        if f then
            profileString = f:read("*all")
            f:close()
        end
    end
    
    return profileString
end

-- Import the profile string to Plater
function PlaterProfileImport.ImportToPlater(profileString)
    -- Check if Plater is loaded
    if not IsAddOnLoaded("Plater") then
        return false, "Plater is not installed or enabled"
    end
    
    -- Check if we have a valid profile string
    if not profileString or profileString == "" then
        return false, "Invalid profile string"
    end
    
    -- Call Plater's import function
    local success = false
    
    -- Use pcall to catch any errors
    local status, result = pcall(function()
        -- Try to import via Plater's API
        if Plater and Plater.ImportProfile then
            success = Plater.ImportProfile(profileString)
        end
    end)
    
    -- Return the result
    if success then
        return true, "Successfully imported profile to Plater"
    else
        return false, "Failed to import profile to Plater: " .. (result or "Unknown error")
    end
end

-- Create importer button for options panel
function PlaterProfileImport.CreateImporterButton(parent)
    -- Create a button for the options panel
    local button = CreateFrame("Button", nil, parent, "UIPanelButtonTemplate")
    button:SetSize(200, 24)
    button:SetText("Import to Plater")
    button:SetPoint("TOPLEFT", parent, "TOPLEFT", 20, -20)
    
    -- Set up the click handler
    button:SetScript("OnClick", function()
        local success, message = PlaterProfileImport.ImportPlaterProfile(M)
        if success then
            print("|cFF00FF00[VUIPlater]|r Profile imported to Plater successfully!")
        else
            print("|cFFFF0000[VUIPlater]|r Error importing profile: " .. (message or "Unknown error"))
        end
    end)
    
    return button
end 